CREATE TABLE "AdminUser" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"username" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "AdminUser_username_key" ON "AdminUser"("username");
CREATE TABLE "LiveSession" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"title" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT false,"coins" INTEGER NOT NULL DEFAULT 0,"startedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" DATETIME);
CREATE TABLE "TikTokViewer" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"userId" TEXT NOT NULL,"username" TEXT NOT NULL,"displayName" TEXT NOT NULL,"avatarUrl" TEXT,"totalCoins" INTEGER NOT NULL DEFAULT 0,"giftCount" INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX "TikTokViewer_userId_key" ON "TikTokViewer"("userId");
CREATE TABLE "TikTokEvent" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"eventId" TEXT NOT NULL,"type" TEXT NOT NULL,"viewerId" TEXT NOT NULL,"simulated" BOOLEAN NOT NULL DEFAULT false,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "TikTokEvent_eventId_key" ON "TikTokEvent"("eventId");
CREATE TABLE "GiftCatalogItem" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"giftId" TEXT NOT NULL,"name" TEXT NOT NULL,"icon" TEXT NOT NULL,"coinValue" INTEGER NOT NULL);
CREATE UNIQUE INDEX "GiftCatalogItem_giftId_key" ON "GiftCatalogItem"("giftId");
CREATE TABLE "GiftEvent" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"eventId" TEXT NOT NULL,"giftId" TEXT NOT NULL,"viewerId" TEXT NOT NULL,"comboId" TEXT,"repeatCount" INTEGER NOT NULL,"creditedCount" INTEGER NOT NULL DEFAULT 0,"coins" INTEGER NOT NULL,"simulated" BOOLEAN NOT NULL DEFAULT false,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "GiftEvent_eventId_key" ON "GiftEvent"("eventId");
CREATE TABLE "GiftRule" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"giftId" TEXT NOT NULL,"name" TEXT NOT NULL,"icon" TEXT NOT NULL,"coinValue" INTEGER NOT NULL,"action" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"requiresComment" BOOLEAN NOT NULL DEFAULT false,"themeDuration" INTEGER,"alertTemplate" TEXT);
CREATE UNIQUE INDEX "GiftRule_giftId_key" ON "GiftRule"("giftId");
CREATE TABLE "Track" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"key" TEXT NOT NULL,"title" TEXT NOT NULL,"artist" TEXT NOT NULL,"albumUrl" TEXT,"durationMs" INTEGER NOT NULL DEFAULT 180000,"spotifyUri" TEXT,"lyrics" TEXT);
CREATE UNIQUE INDEX "Track_key_key" ON "Track"("key");
CREATE TABLE "SongRequest" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"trackId" INTEGER,"query" TEXT NOT NULL,"requesterIds" TEXT NOT NULL,"requesterNames" TEXT NOT NULL,"priority" BOOLEAN NOT NULL DEFAULT false,"status" TEXT NOT NULL DEFAULT 'PENDING',"position" INTEGER NOT NULL DEFAULT 0,"coins" INTEGER NOT NULL DEFAULT 0,"carryOver" BOOLEAN NOT NULL DEFAULT false,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SongRequest_trackId_fkey" FOREIGN KEY("trackId") REFERENCES "Track"("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "PlaybackHistory" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"trackTitle" TEXT NOT NULL,"artist" TEXT NOT NULL,"status" TEXT NOT NULL,"playedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SkipVote" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"requestId" INTEGER NOT NULL,"viewerId" TEXT NOT NULL,"viewerName" TEXT NOT NULL,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SkipVote_requestId_viewerId_key" ON "SkipVote"("requestId","viewerId");
CREATE TABLE "Theme" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"slug" TEXT NOT NULL,"name" TEXT NOT NULL,"background" TEXT NOT NULL,"cardColor" TEXT NOT NULL,"borderColor" TEXT NOT NULL,"particle" TEXT NOT NULL,"isDefault" BOOLEAN NOT NULL DEFAULT false);
CREATE UNIQUE INDEX "Theme_slug_key" ON "Theme"("slug");
CREATE TABLE "ThemeActivation" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"themeId" INTEGER NOT NULL,"activatedBy" TEXT,"expiresAt" DATETIME,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BlockedUser" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"userId" TEXT NOT NULL,"reason" TEXT); CREATE UNIQUE INDEX "BlockedUser_userId_key" ON "BlockedUser"("userId");
CREATE TABLE "BlockedTrack" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"trackKey" TEXT NOT NULL,"reason" TEXT); CREATE UNIQUE INDEX "BlockedTrack_trackKey_key" ON "BlockedTrack"("trackKey");
CREATE TABLE "BlockedArtist" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"artist" TEXT NOT NULL,"reason" TEXT); CREATE UNIQUE INDEX "BlockedArtist_artist_key" ON "BlockedArtist"("artist");
CREATE TABLE "AppSetting" ("key" TEXT NOT NULL PRIMARY KEY,"value" TEXT NOT NULL,"updatedAt" DATETIME NOT NULL);
CREATE TABLE "SpotifyAccount" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"accessTokenEncrypted" TEXT,"refreshTokenEncrypted" TEXT,"expiresAt" DATETIME,"deviceId" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,"action" TEXT NOT NULL,"actor" TEXT NOT NULL,"details" TEXT,"createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
